$path = "reset-password.html"
$b64 = ""
$bytes = [Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) $path), $bytes)
$check = [System.IO.File]::ReadAllText((Join-Path (Get-Location) $path))
if ($check.Contains("Reset Your Password")) { Write-Output "Heading text: OK" } else { Write-Output "Heading text: MISSING" }
if ($check.Contains("Password reset successfully.")) { Write-Output "Success message: OK" } else { Write-Output "Success message: MISSING" }
if ($check.Contains("This password reset link is invalid or has expired.")) { Write-Output "Invalid-link message: OK" } else { Write-Output "Invalid-link message: MISSING" }
Write-Output "Now run: firebase deploy --only hosting"
